-- FAQ de Teclab, tanda 4a (28/11/2026): Gestión Contable (227), Administración de Empresas (242)
-- y Comercio Electrónico (248) de 5 a 9; Higiene y Seguridad en el Trabajo (245) de 5 a 8.
-- Textos aprobados por el usuario. Fuentes: fichas oficiales de teclab.edu.ar y plan en D1.
-- Sin «título oficial con acreditación nacional» en 242 y 245: sus fichas oficiales no lo dicen.
-- Cada UPDATE exige el JSON y el título actuales: si alguno cambió, no escribe.
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Gestión Contable?","respuesta":"Aprendés contabilidad, análisis de estados contables, liquidación de impuestos y sueldos y legislación laboral. Usás software de gestión e inteligencia artificial para agilizar registros, conciliaciones e informes contables."},{"pregunta":"¿Cuál es la diferencia entre Gestión Contable y Contador Público?","respuesta":"Gestión Contable es una tecnicatura orientada al registro, control y análisis de información contable. Es una formación distinta de la carrera universitaria de Contador Público y no otorga ese título."},{"pregunta":"¿Puedo continuar con Contador Público después de Gestión Contable?","respuesta":"Podés consultar la articulación con Contador Público en Universidad Siglo 21. Las equivalencias se evalúan según tu trayectoria académica; no son automáticas."},{"pregunta":"¿Qué hace un técnico en gestión contable?","respuesta":"Registra operaciones, controla la documentación de los circuitos administrativos, analiza estados contables y aplica conocimientos impositivos y laborales. Trabaja en estudios contables, pymes y áreas administrativas o impositivas de empresas, como auxiliar contable, asistente administrativo o analista impositivo."},{"pregunta":"¿Cuánto dura la Tecnicatura en Gestión Contable?","respuesta":"Dura 2 años y se cursa 100% online. Te recibís de Técnico Superior en Gestión Contable y en el camino obtenés el certificado intermedio de Auxiliar Contable."},{"pregunta":"¿Cómo se cursa?","respuesta":"100% online, con clases en vivo que quedan grabadas y actividades prácticas, así que podés combinarla con el trabajo."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con Fundamentos de contabilidad y Circuitos administrativos contables clave en el primer cuatrimestre."},{"pregunta":"¿Puedo empezar a trabajar antes de terminar?","respuesta":"Sí. Al completar el primer año obtenés el certificado intermedio, que acredita conocimientos para colaborar en tareas administrativas y contables, como el registro de comprobantes, la gestión de proveedores y el seguimiento de pagos."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. En el último cuatrimestre hacés Práctica profesional I y II, donde aplicás lo aprendido a situaciones de trabajo."}]}]' WHERE id = 227 AND titulo = 'Técnico Superior en Gestión Contable' AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Gestión Contable?","respuesta":"Aprendés contabilidad, análisis de estados contables, liquidación de impuestos y sueldos y legislación laboral. Usás software de gestión e inteligencia artificial para agilizar registros, conciliaciones e informes contables."},{"pregunta":"¿Cuál es la diferencia entre Gestión Contable y Contador Público?","respuesta":"Gestión Contable es una tecnicatura orientada al registro, control y análisis de información contable. Es una formación distinta de la carrera universitaria de Contador Público y no otorga ese título."},{"pregunta":"¿Puedo continuar con Contador Público después de Gestión Contable?","respuesta":"Podés consultar la articulación con Contador Público en Universidad Siglo 21. Las equivalencias se evalúan según tu trayectoria académica; no son automáticas."},{"pregunta":"¿Qué hace un técnico en gestión contable?","respuesta":"Registra operaciones, controla la documentación de los circuitos administrativos, analiza estados contables y aplica conocimientos impositivos y laborales. Trabaja en estudios contables, pymes y áreas administrativas o impositivas de empresas, como auxiliar contable, asistente administrativo o analista impositivo."},{"pregunta":"¿Cuánto dura la Tecnicatura en Gestión Contable?","respuesta":"Dura 2 años y se cursa 100% online. Te recibís de Técnico Superior en Gestión Contable y en el camino obtenés el certificado intermedio de Auxiliar Contable."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Administración de Empresas?","respuesta":"Estudiás contabilidad, técnica impositiva, operaciones financieras, presupuestos y costos, junto con relaciones laborales, desarrollo humano, sociedades comerciales, inteligencia de negocios y transformación e innovación organizacional."},{"pregunta":"¿Qué hace un técnico en Administración de Empresas?","respuesta":"Registra y analiza datos administrativos, contables y financieros, planifica recursos, controla gastos y analiza costos, participa en cambios e innovación dentro de la organización y usa información de negocio y herramientas de gestión para apoyar las decisiones."},{"pregunta":"¿Cuál es la salida laboral de Administración de Empresas?","respuesta":"Empresas privadas, en presupuestos, gestión administrativa y operaciones; organismos públicos, en planificación y control de programas y recursos; emprendimientos propios, en el desarrollo y la administración de proyectos de negocio, y consultoría y servicios, en mejora de procesos y apoyo a la gestión organizacional."},{"pregunta":"¿Tiene certificado intermedio?","respuesta":"Sí. Al completar el primer año obtenés el certificado de Asistente en Administración de Empresas, y al egresar, el título de Técnico Superior en Administración de Empresas."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. La Práctica Profesionalizante es obligatoria y puede incluir instancias presenciales, híbridas o remotas, según informa Teclab."},{"pregunta":"¿Cuánto dura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa a distancia, con clases en vivo que quedan grabadas y actividades prácticas desde el comienzo."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No hace falta saber de administración. Para ingresar tenés que tener el secundario completo y cumplir los requisitos de admisión vigentes."},{"pregunta":"¿Incluye herramientas digitales e inteligencia artificial?","respuesta":"Sí. El plan incorpora herramientas digitales, inteligencia artificial aplicada a la gestión y automatización de procesos, y en el último cuatrimestre cursás Inteligencia de negocios."},{"pregunta":"¿Puedo empezar a trabajar antes de terminar?","respuesta":"El certificado intermedio que obtenés al completar el primer año acredita conocimientos para colaborar, con supervisión, en tareas administrativas, gestión documental y reportes básicos."}]}]' WHERE id = 242 AND titulo = 'Técnico Superior en Administración de Empresas' AND slides = '[{"type": "faq", "items": [{"pregunta": "¿Qué se aprende en la Tecnicatura en Administración de Empresas?", "respuesta": "Estudiás contabilidad, técnica impositiva, operaciones financieras, presupuestos y costos, junto con relaciones laborales, desarrollo humano, sociedades comerciales, inteligencia de negocios y transformación e innovación organizacional."}, {"pregunta": "¿Qué hace un técnico en Administración de Empresas?", "respuesta": "Registra y analiza datos administrativos, contables y financieros, planifica recursos, controla gastos y analiza costos, participa en cambios e innovación dentro de la organización y usa información de negocio y herramientas de gestión para apoyar las decisiones."}, {"pregunta": "¿Cuál es la salida laboral de Administración de Empresas?", "respuesta": "Empresas privadas, en presupuestos, gestión administrativa y operaciones; organismos públicos, en planificación y control de programas y recursos; emprendimientos propios, en el desarrollo y la administración de proyectos de negocio, y consultoría y servicios, en mejora de procesos y apoyo a la gestión organizacional."}, {"pregunta": "¿Tiene certificado intermedio?", "respuesta": "Sí. Al completar el primer año obtenés el certificado de Asistente en Administración de Empresas, y al egresar, el título de Técnico Superior en Administración de Empresas."}, {"pregunta": "¿Tiene prácticas?", "respuesta": "Sí. La Práctica Profesionalizante es obligatoria y puede incluir instancias presenciales, híbridas o remotas, según informa Teclab."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Higiene y Seguridad en el Trabajo?","respuesta":"Estudiás gestión de la seguridad y la salud en el trabajo, legislación, identificación y evaluación de riesgos, sustancias químicas, planes de emergencia, física aplicada a ambientes laborales, auditoría de seguridad y sistemas de calidad."},{"pregunta":"¿Qué hace un técnico en Higiene y Seguridad en el Trabajo?","respuesta":"Identifica peligros y propone medidas preventivas, aplica mediciones y evalúa puestos de trabajo, participa en sistemas de seguridad y salud ocupacional y colabora en planes de evacuación y respuesta a contingencias."},{"pregunta":"¿Cuál es la salida laboral de Higiene y Seguridad en el Trabajo?","respuesta":"Empresas e industrias, en prevención de riesgos en entornos productivos; organismos públicos, en aplicación de normas y evaluación de condiciones de trabajo; salud y educación, en programas de prevención y control ambiental laboral, y consultoras especializadas, en inspecciones, auditorías y capacitación en seguridad."},{"pregunta":"¿Tiene certificado intermedio?","respuesta":"Sí. Al completar el primer año obtenés el certificado de Asistente en Higiene y Seguridad en el Trabajo, y al egresar, el título de Técnico Superior en Higiene y Seguridad en el Trabajo."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. La Práctica Profesionalizante es obligatoria y puede incluir instancias presenciales, híbridas o remotas, según informa Teclab."},{"pregunta":"¿Cuánto dura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa a distancia, con clases en vivo que quedan grabadas y actividades prácticas."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No hace falta tener conocimientos técnicos previos. La carrera arranca con Gestión de la seguridad y la salud en el trabajo y Seguridad y gestión de las sustancias químicas."},{"pregunta":"¿Puedo empezar a trabajar antes de terminar?","respuesta":"El certificado intermedio que obtenés al completar el primer año acredita conocimientos para colaborar, con supervisión, en tareas de prevención, registro de riesgos y documentación técnica."}]}]' WHERE id = 245 AND titulo = 'Técnico Superior en Higiene y Seguridad en el Trabajo' AND slides = '[{"type": "faq", "items": [{"pregunta": "¿Qué se aprende en la Tecnicatura en Higiene y Seguridad en el Trabajo?", "respuesta": "Estudiás gestión de la seguridad y la salud en el trabajo, legislación, identificación y evaluación de riesgos, sustancias químicas, planes de emergencia, física aplicada a ambientes laborales, auditoría de seguridad y sistemas de calidad."}, {"pregunta": "¿Qué hace un técnico en Higiene y Seguridad en el Trabajo?", "respuesta": "Identifica peligros y propone medidas preventivas, aplica mediciones y evalúa puestos de trabajo, participa en sistemas de seguridad y salud ocupacional y colabora en planes de evacuación y respuesta a contingencias."}, {"pregunta": "¿Cuál es la salida laboral de Higiene y Seguridad en el Trabajo?", "respuesta": "Empresas e industrias, en prevención de riesgos en entornos productivos; organismos públicos, en aplicación de normas y evaluación de condiciones de trabajo; salud y educación, en programas de prevención y control ambiental laboral, y consultoras especializadas, en inspecciones, auditorías y capacitación en seguridad."}, {"pregunta": "¿Tiene certificado intermedio?", "respuesta": "Sí. Al completar el primer año obtenés el certificado de Asistente en Higiene y Seguridad en el Trabajo, y al egresar, el título de Técnico Superior en Higiene y Seguridad en el Trabajo."}, {"pregunta": "¿Tiene prácticas?", "respuesta": "Sí. La Práctica Profesionalizante es obligatoria y puede incluir instancias presenciales, híbridas o remotas, según informa Teclab."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Cuánto dura la carrera?","respuesta":"Dura 2 años y se cursa 100% online, con una Práctica Profesionalizante en el último cuatrimestre."},{"pregunta":"¿Qué diferencia hay con un curso para crear una tienda online?","respuesta":"La tecnicatura aborda el negocio completo: plataformas, catálogos, campañas, experiencia del cliente, medios de pago, logística y análisis de resultados."},{"pregunta":"¿Qué certificado intermedio ofrece?","respuesta":"Asistente en Comercio Electrónico (e-commerce), al completar el primer año."},{"pregunta":"¿Se estudian logística y medios de pago?","respuesta":"Sí. El segundo año incluye Logística para Negocios Digitales y Regulación y Medios de Pago."},{"pregunta":"¿Qué título se obtiene?","respuesta":"Técnico Superior en Comercio Electrónico (e-commerce)."},{"pregunta":"¿Voy a aprender a gestionar marketplaces y tiendas online?","respuesta":"Sí. En Gestión de comercio electrónico trabajás la configuración de tiendas, los catálogos, la integración de canales y la operación de marketplaces."},{"pregunta":"¿Qué herramientas de marketing se estudian?","respuesta":"SEO para e-commerce, contenidos comerciales, publicidad digital y análisis de campañas y métricas de conversión, con herramientas como Google Ads, Meta Ads y Mercado Ads."},{"pregunta":"¿Incluye inteligencia artificial y análisis de datos?","respuesta":"Sí. A lo largo de la carrera se aplican herramientas de IA y automatización, y en el último cuatrimestre cursás Inteligencia de negocios para interpretar información y tomar decisiones."},{"pregunta":"¿Necesito tener un emprendimiento para estudiar?","respuesta":"No. La carrera sirve tanto para sumarte a equipos de negocios digitales como para desarrollar o mejorar un canal de venta propio."}]}]' WHERE id = 248 AND titulo = 'Técnico Superior en Comercio Electrónico (e-commerce)' AND slides = '[{"type":"faq","items":[{"pregunta":"¿Cuánto dura la carrera?","respuesta":"Dura 2 años y se cursa 100% online, con una Práctica Profesionalizante en el último cuatrimestre."},{"pregunta":"¿Qué diferencia hay con un curso para crear una tienda online?","respuesta":"La tecnicatura aborda el negocio completo: plataformas, catálogos, campañas, experiencia del cliente, medios de pago, logística y análisis de resultados."},{"pregunta":"¿Qué certificado intermedio ofrece?","respuesta":"Asistente en Comercio Electrónico (e-commerce), al completar el primer año."},{"pregunta":"¿Se estudian logística y medios de pago?","respuesta":"Sí. El segundo año incluye Logística para Negocios Digitales y Regulación y Medios de Pago."},{"pregunta":"¿Qué título se obtiene?","respuesta":"Técnico Superior en Comercio Electrónico (e-commerce)."}]}]';
